/// `ENV_HINT`: fail at the earliest point that can name the fix.
fn require_proto_patch(
    manifest_dir: &std::path::Path,
    proto_dir: &std::path::Path,
    applied: impl Fn(&str) -> bool,
    patch_relpath: &str,
